import { useEffect, useState } from "react";

export default function AdminGallery() {
  const [images, setImages] = useState([]);
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState("");

  // Load gallery
  const fetchImages = async () => {
    const res = await fetch("http://localhost:5001/admin/gallery");
    const data = await res.json();
    setImages(data);
  };

  useEffect(() => {
    fetchImages();
  }, []);

  // Select image
  const handleFileChange = (e) => {
    const selected = e.target.files[0];
    setFile(selected);
    setPreview(URL.createObjectURL(selected));
    setSuccess("");
  };

  // Upload image
  const handleUpload = async () => {
    if (!file) return;

    setLoading(true);
    setSuccess("");

    const formData = new FormData();
    formData.append("image", file);

    try {
      const res = await fetch("http://localhost:5001/admin/gallery", {
        method: "POST",
        headers: {
          Authorization: "Bearer " + localStorage.getItem("adminToken"),
        },
        body: formData,
      });

      const data = await res.json(); // 🔥 IMPORTANT

      if (res.ok) {
        // ✅ INSTANT UI UPDATE (NO WAIT)
        setImages((prev) => [
          {
            id: Date.now(),
            image_url: data.image_url,
          },
          ...prev,
        ]);

        setSuccess("✅ Image uploaded successfully");
        setFile(null);
        setPreview(null);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-8 text-white">
      <h1 className="text-3xl font-bold text-yellow-400 mb-6">
        Gallery Manager
      </h1>

      {/* Upload box */}
      <div className="bg-[#111] border border-yellow-500 rounded-xl p-6 max-w-xl">
        <input
          type="file"
          accept="image/*"
          onChange={handleFileChange}
          className="mb-4 block w-full text-sm text-gray-300
          file:bg-yellow-400 file:text-black file:border-0
          file:px-4 file:py-2 file:rounded-lg"
        />

        {preview && (
          <div className="mb-4">
            <p className="text-sm text-gray-400 mb-2">Preview</p>
            <img
              src={preview}
              alt="preview"
              className="w-40 h-40 object-cover rounded-lg border border-yellow-500"
            />
          </div>
        )}

        <button
          onClick={handleUpload}
          disabled={loading}
          className="bg-yellow-400 text-black px-6 py-2 rounded-lg font-semibold hover:bg-yellow-500 transition"
        >
          {loading ? "Uploading..." : "Upload Image"}
        </button>

        {success && (
          <p className="mt-4 text-green-400 font-semibold">{success}</p>
        )}
      </div>

      {/* Gallery */}
      <h2 className="text-xl font-semibold mt-10 mb-4 text-yellow-400">
        Uploaded Images
      </h2>

      {images.length === 0 ? (
        <p className="text-gray-400">No images uploaded yet</p>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
          {images.map((img) => (
            <div
              key={img.id}
              className="border border-yellow-500 rounded-lg overflow-hidden"
            >
              <img
                src={`http://localhost:5001${img.image_url}?t=${Date.now()}`}
                alt=""
                className="w-full h-40 object-cover hover:scale-105 transition"
              />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
